/** Return reusable artwork markup. Omitting paper keeps the brand logo transparent. */
export function graffitiPinArtwork(ink = '#242B24', paper?: string): string {
  const body = paper ? '<path d="' + OUTER_BODY + '" fill="' + paper + '"/>' : '';
  const cutout = '<defs><mask id="pin-center-cutout" maskUnits="userSpaceOnUse" x="0" y="0" width="320" height="360"><rect width="320" height="360" fill="white"/><path d="' + CENTER_CUTOUT + '" fill="black"/></mask></defs>';
  return cutout + '<g mask="url(#pin-center-cutout)">' + body + '<path d="' + RING_OUTLINE + '" fill="none" stroke="' + ink + '" stroke-width="3" stroke-linejoin="round" opacity="0.18"/><path d="' + RING_OUTLINE + '" fill="' + ink + '" fill-rule="evenodd"/>' +
    TIP_CLOSURE.replaceAll('__INK__', ink) + ROUGH_DETAILS.replaceAll('#171916', ink) + DRIPS.replaceAll('__INK__', ink) + '</g>';
}

/** Return a complete SVG. The map uses the default 44 by 50 display size. */
export function graffitiPinSvg(ink = '#242B24', paper?: string): string {
  return '<svg xmlns="http://www.w3.org/2000/svg" width="44" height="50" viewBox="0 0 320 360">' +
    graffitiPinArtwork(ink, paper) + '</svg>';
}

/** Single map marker; selected markers use a lime pin body. */
export function graffitiPinMarkerSvg(selected = false): string {
  return graffitiPinSvg('#242B24', selected ? '#DFFF65' : '#F9FAF5');
}
